package com.wiseway.service;
import java.util.*; import org.springframework.stereotype.Service;
@Service public class GeocodingService { private final LocationService catalog; private final Optional<GeocodingProvider> external; private final OsmTransitRoutingProvider transit; public GeocodingService(LocationService c,Optional<GeocodingProvider> e,OsmTransitRoutingProvider t){catalog=c;external=e;transit=t;} public List<LocationService.Location> search(String q){var places=external.map(x->x.search(q)).orElseGet(()->catalog.search(q));var stops=transit.searchStops(q);return java.util.stream.Stream.concat(stops.stream(),places.stream()).distinct().limit(12).toList();} }
